import { Textarea } from '@refy-design/web';
import { VoiceRecorder } from '@refy-design/web';
import type { VoiceRecorderState } from '@refy-design/web';
import { useEffect } from 'react';
import { useState } from 'react';
function RecorderDemo({ initialState }: { initialState: VoiceRecorderState }) {
  const [state, setState] = useState<VoiceRecorderState>(initialState);
  const [duration, setDuration] = useState(initialState === 'paused' ? 18 : 0);
  const [transcript, setTranscript] = useState('');
  const [level, setLevel] = useState(36);
  const [message, setMessage] = useState(`Current state: ${initialState}.`);
  useEffect(() => {
    if (state !== 'listening') return;
    const timer = window.setInterval(() => {
      setDuration((value) => value + 1);
      setLevel((value) => ((value + 17) % 96) + 4);
    }, 1000);
    return () => window.clearInterval(timer);
  }, [state]);
  const transition = (next: VoiceRecorderState, copy: string) => {
    setState(next);
    setMessage(copy);
  };
  return (
    <div style={{ display: 'grid', gap: 12, maxWidth: 620 }}>
      <VoiceRecorder
        state={state}
        duration={duration}
        level={level}
        onStart={() => {
          setTranscript('');
          transition('listening', 'Simulation started, no audio captured.');
        }}
        onPause={() => transition('paused', 'Recording paused.')}
        onResume={() => transition('listening', 'Recording resumed.')}
        onCancel={() => {
          setDuration(0);
          transition('idle', 'Recording discarded.');
        }}
        onFinish={() => {
          setTranscript(
            "Let's review the project materials before sharing them with the team.",
          );
          transition('idle', 'Simulation done. Review the sample text.');
        }}
        onRetry={() => transition('idle', 'Simulation restarted.')}
        onUseFallback={() =>
          transition(
            state === 'error' ? 'fallback' : 'idle',
            state === 'error'
              ? 'Dictation fallback shown.'
              : 'Continue with the phone keyboard.',
          )
        }
      />
      {transcript && (
        <Textarea
          label="Sample text for review"
          value={transcript}
          onChange={(event) => setTranscript(event.target.value)}
        />
      )}
      <p
        role="status"
        style={{ margin: 0, color: 'var(--ink-3)', fontSize: 'var(--text-xs)' }}
      >
        {message}
      </p>
    </div>
  );
}
export function Example() {
  return <RecorderDemo initialState="idle" />;
}

